@Component({
  selector: 'lib-lucent-tab',
  standalone: true,
  imports: [CommonModule],
  template: `
    <div class="lucent-tabs">
      <div class="lucent-tab-list">
        <button *ngFor="let tab of tabs; let i = index"
                class="lucent-tab-button"
